/* spacepussy.ai/explorer — the network tab: who the explorer's node sees on the wire, on a globe of pink dots.
   reads one static file, data/network.json (site/explorer/indexer/network.py, rewritten every ~30 s), and the page's
   live tip (explorer.js: LIVE, the /tip poll); no other request. loaded by explorer.js on #/network; uses its helpers.
   the land is Natural Earth 1:110m (public domain) as a 0.5° bitmask (indexer/landmask.py); no library, plain canvas. */
'use strict';

const LAND = '';
const LAND_ROWS = 360; const LAND_COLS = 720; const LAND_STEP = 0.5;
const D2R = Math.PI / 180;
const NETCOL = { pink: '255,45,146', pale: '255,163,209', blue: '0,184,255', ink: '242,242,242' };

const NW = {
  data: null, at: 0,                 // network.json and when it was read
  cv: null, g: null, W: 0, H: 0, dpr: 1, R: 0,
  lon0: 0, lat0: 22, zoom: 1, home: null,
  auto: !matchMedia('(prefers-reduced-motion: reduce)').matches, idleUntil: 0,
  drag: null, pinch: null, hover: null, raf: 0, last: 0,
  groups: [], dots: { 1: null, 0.5: null }, sprite: {},
};

/* ------------------------------------------------------------------ the land as dots */
function landBits() {
  if (NW.bits) return NW.bits;
  const s = atob(LAND); const b = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) b[i] = s.charCodeAt(i);
  return (NW.bits = b);
}
const isLand = (lat, lon) => {
  const r = Math.min(LAND_ROWS - 1, Math.max(0, Math.floor((90 - lat) / LAND_STEP)));
  const c = ((Math.floor((lon + 180) / LAND_STEP) % LAND_COLS) + LAND_COLS) % LAND_COLS;
  const i = r * LAND_COLS + c;
  return (landBits()[i >> 3] & (0x80 >> (i & 7))) !== 0;
};
// equal-area dots: rows every `step` degrees, as many dots per row as the circle of latitude holds, alternate rows offset
function landDots(step) {
  if (NW.dots[step]) return NW.dots[step];
  const sl = []; const cl = []; const lo = [];
  let row = 0;
  for (let lat = 90 - step / 2; lat > -90; lat -= step, row++) {
    const n = Math.max(1, Math.round((360 / step) * Math.cos(lat * D2R)));
    const off = row % 2 ? 0.5 : 0;
    for (let k = 0; k < n; k++) {
      const lon = -180 + ((k + off) * 360) / n;
      if (isLand(lat, lon)) { sl.push(Math.sin(lat * D2R)); cl.push(Math.cos(lat * D2R)); lo.push(lon * D2R); }
    }
  }
  return (NW.dots[step] = { sl: Float32Array.from(sl), cl: Float32Array.from(cl), lo: Float32Array.from(lo), n: sl.length });
}

/* ------------------------------------------------------------------ projection: orthographic, centred on (lon0, lat0) */
function proj(lat, lon, r = 1) {
  const p = lat * D2R; const dl = (lon - NW.lon0) * D2R; const p0 = NW.lat0 * D2R;
  const cp = Math.cos(p); const sp = Math.sin(p);
  const x = cp * Math.sin(dl) * r;
  const y = (Math.cos(p0) * sp - Math.sin(p0) * cp * Math.cos(dl)) * r;
  const z = (Math.sin(p0) * sp + Math.cos(p0) * cp * Math.cos(dl)) * r;
  return { x: NW.W / 2 + NW.R * x, y: NW.H / 2 - NW.R * y, z, vis: z > 0 || x * x + y * y > 1 };
}
const toVec = (lat, lon) => [Math.cos(lat * D2R) * Math.cos(lon * D2R), Math.cos(lat * D2R) * Math.sin(lon * D2R), Math.sin(lat * D2R)];
const fromVec = (v) => [Math.atan2(v[2], Math.hypot(v[0], v[1])) / D2R, Math.atan2(v[1], v[0]) / D2R];

function glow(rgb, size) {      // a soft dot, drawn once, stamped many times
  const key = `${rgb}:${size}`; if (NW.sprite[key]) return NW.sprite[key];
  const c = document.createElement('canvas'); const s = Math.ceil(size * 2 * NW.dpr); c.width = c.height = s;
  const g = c.getContext('2d'); const gr = g.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
  gr.addColorStop(0, `rgba(${rgb},.95)`); gr.addColorStop(0.18, `rgba(${rgb},.6)`); gr.addColorStop(0.5, `rgba(${rgb},.14)`); gr.addColorStop(1, `rgba(${rgb},0)`);
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
  return (NW.sprite[key] = c);
}

/* ------------------------------------------------------------------ the frame */
function frame(t) {
  NW.raf = 0;
  const cv = NW.cv;
  if (!cv || !cv.isConnected) { NW.cv = null; return; }
  const dt = NW.last ? Math.min(100, t - NW.last) : 16; NW.last = t;
  if (NW.auto && !NW.drag && t > NW.idleUntil) NW.lon0 = ((NW.lon0 - dt * 0.004 + 540) % 360) - 180;
  const rect = cv.getBoundingClientRect();
  if (rect.bottom > 0 && rect.top < innerHeight) draw(t);
  NW.raf = requestAnimationFrame(frame);
}
function kick() { if (!NW.raf && NW.cv) NW.raf = requestAnimationFrame(frame); }

function draw(t) {
  const { g, W, H } = NW; const R = NW.R = Math.min(W, H) * 0.42 * NW.zoom;
  const cx = W / 2; const cy = H / 2;
  g.setTransform(NW.dpr, 0, 0, NW.dpr, 0, 0); g.clearRect(0, 0, W, H);
  // the halo, then the sphere: near-black with a pink breath at the limb
  let gr = g.createRadialGradient(cx, cy, R * 0.9, cx, cy, R * 1.35);
  gr.addColorStop(0, `rgba(${NETCOL.pink},.20)`); gr.addColorStop(0.3, `rgba(${NETCOL.pink},.06)`); gr.addColorStop(1, `rgba(${NETCOL.pink},0)`);
  g.fillStyle = gr; g.beginPath(); g.arc(cx, cy, R * 1.35, 0, 7); g.fill();
  gr = g.createRadialGradient(cx - R * 0.35, cy - R * 0.4, R * 0.1, cx, cy, R);
  gr.addColorStop(0, '#1a0811'); gr.addColorStop(0.75, '#070306'); gr.addColorStop(1, '#14040c');
  g.fillStyle = gr; g.beginPath(); g.arc(cx, cy, R, 0, 7); g.fill();
  g.strokeStyle = `rgba(${NETCOL.pink},.55)`; g.lineWidth = 1.2; g.beginPath(); g.arc(cx, cy, R, 0, 7); g.stroke();
  // graticule every 30°: front only, faint
  g.strokeStyle = `rgba(${NETCOL.pink},.10)`; g.lineWidth = 1;
  const line = (pts) => { g.beginPath(); let on = false; for (const [la, lo] of pts) { const p = proj(la, lo); if (p.z > 0) { if (on) g.lineTo(p.x, p.y); else g.moveTo(p.x, p.y); on = true; } else on = false; } g.stroke(); };
  for (let lo = -180; lo < 180; lo += 30) { const pts = []; for (let la = -90; la <= 90; la += 3) pts.push([la, lo]); line(pts); }
  for (let la = -60; la <= 60; la += 30) { const pts = []; for (let lo = -180; lo <= 180; lo += 3) pts.push([la, lo]); line(pts); }
  // the land: dots in four depth buckets (one fill each), the far side as a ghost
  const step = NW.zoom >= 2.4 ? 0.5 : 1; const D = landDots(step);
  const p0 = NW.lat0 * D2R; const sp0 = Math.sin(p0); const cp0 = Math.cos(p0); const l0 = NW.lon0 * D2R;
  const size = Math.max(0.9, R * step * D2R * 0.36);
  const paths = [new Path2D(), new Path2D(), new Path2D(), new Path2D(), new Path2D()];
  for (let i = 0; i < D.n; i++) {
    const dl = D.lo[i] - l0; const cl = D.cl[i]; const cdl = Math.cos(dl);
    const z = sp0 * D.sl[i] + cp0 * cl * cdl;
    const x = cx + R * cl * Math.sin(dl); const y = cy - R * (cp0 * D.sl[i] - sp0 * cl * cdl);
    if (x < -4 || x > W + 4 || y < -4 || y > H + 4) continue;
    const b = z <= 0 ? 0 : z < 0.25 ? 1 : z < 0.5 ? 2 : z < 0.75 ? 3 : 4;
    const s = b ? size * (0.55 + 0.45 * z) : size * 0.6;
    paths[b].rect(x - s / 2, y - s / 2, s, s);
  }
  const alpha = [0.05, 0.28, 0.45, 0.62, 0.8];
  paths.forEach((p, b) => { g.fillStyle = `rgba(${b ? NETCOL.pink : NETCOL.pale},${alpha[b]})`; g.fill(p); });

  // the wire: from the explorer's node to every node online now, lifted over the surface, a light running along it
  const home = NW.groups.find((x) => x.self);
  if (home) {
    const a = toVec(home.lat, home.lon);
    NW.groups.forEach((gp, k) => {
      if (gp === home || !gp.online) return;
      const b = toVec(gp.lat, gp.lon);
      const ang = Math.acos(Math.max(-1, Math.min(1, a[0] * b[0] + a[1] * b[1] + a[2] * b[2])));
      if (ang < 1e-4) return;
      const N = 48; const pts = [];
      for (let i = 0; i <= N; i++) {
        const f = i / N; const s1 = Math.sin((1 - f) * ang) / Math.sin(ang); const s2 = Math.sin(f * ang) / Math.sin(ang);
        const [la, lo] = fromVec([a[0] * s1 + b[0] * s2, a[1] * s1 + b[1] * s2, a[2] * s1 + b[2] * s2]);
        pts.push(proj(la, lo, 1 + 0.22 * Math.sin(Math.PI * f) * (ang / Math.PI)));
      }
      g.strokeStyle = `rgba(${NETCOL.pink},.55)`; g.lineWidth = 1.3; g.beginPath(); let on = false;
      for (const p of pts) { if (p.vis) { if (on) g.lineTo(p.x, p.y); else g.moveTo(p.x, p.y); on = true; } else on = false; }
      g.stroke();
      const run = pts[Math.floor(((t / 2600 + k * 0.37) % 1) * N)];
      if (run && run.vis) { const sp = glow(NETCOL.pale, 9); g.drawImage(sp, run.x - 9, run.y - 9, 18, 18); }
    });
  }
  // the nodes: online = bright with a pulse, seen in 24 h = dim, announced only = a blue ring
  NW.screen = [];
  for (const gp of NW.groups) {
    const p = proj(gp.lat, gp.lon); if (p.z <= 0.02) continue;
    const k = Math.sqrt(gp.n); const depth = 0.55 + 0.45 * p.z;
    if (gp.seen) {
      const s = (gp.self ? 26 : 18 + 5 * k) * depth;
      g.globalAlpha = gp.online ? 1 : 0.4;
      g.drawImage(glow(NETCOL.pink, s), p.x - s, p.y - s, 2 * s, 2 * s);
      g.fillStyle = gp.online ? '#fff' : `rgba(${NETCOL.pale},.9)`; g.beginPath(); g.arc(p.x, p.y, (gp.self ? 3.2 : 2.2 + 0.6 * k) * depth, 0, 7); g.fill();
      if (gp.online) {
        const ph = ((t / 1800) + gp.phase) % 1;
        g.strokeStyle = `rgba(${NETCOL.pink},${0.7 * (1 - ph)})`; g.lineWidth = 1.4; g.beginPath(); g.arc(p.x, p.y, (5 + 18 * ph) * depth, 0, 7); g.stroke();
      }
      g.globalAlpha = 1;
    } else {
      g.strokeStyle = `rgba(${NETCOL.blue},.9)`; g.lineWidth = 1.6; g.beginPath(); g.arc(p.x, p.y, 5 * depth, 0, 7); g.stroke();
    }
    if (gp.n > 1) { g.font = '700 10.5px "JetBrains Mono", Menlo, monospace'; g.fillStyle = '#fff'; g.textAlign = 'left'; g.textBaseline = 'middle'; g.fillText(String(gp.n), p.x + 7, p.y - 7); }
    if (gp.label && p.z > 0.15) {
      g.font = '11px "JetBrains Mono", Menlo, monospace'; g.textAlign = 'left'; g.textBaseline = 'middle';
      const tx = p.x + 12; const ty = p.y + (gp.n > 1 ? 9 : 0); const w = g.measureText(gp.label).width;
      g.fillStyle = 'rgba(0,0,0,.6)'; g.fillRect(tx - 4, ty - 8, w + 8, 16);
      g.fillStyle = gp.online ? `rgb(${NETCOL.ink})` : `rgba(${NETCOL.ink},.6)`; g.fillText(gp.label, tx, ty);
    }
    NW.screen.push({ gp, x: p.x, y: p.y });
  }
}

/* ------------------------------------------------------------------ the data on the globe */
function groupNodes(d) {
  const by = new Map();
  for (const n of d.nodes || []) {
    if (n.lat === null || n.lat === undefined) continue;
    const key = `${n.lat},${n.lon}`;
    let gp = by.get(key);
    if (!gp) { gp = { lat: n.lat, lon: n.lon, nodes: [], n: 0, phase: Math.random() }; by.set(key, gp); }
    gp.nodes.push(n); gp.n++;
  }
  for (const gp of by.values()) {
    gp.self = gp.nodes.some((n) => n.direction === 'self');
    gp.online = gp.nodes.some((n) => n.online);
    gp.seen = gp.nodes.some((n) => n.seen);
    const names = gp.nodes.map((n) => n.name).filter(Boolean);
    gp.label = names.length ? names.slice(0, 2).join(' · ') + (names.length > 2 ? ` +${names.length - 2}` : '') : '';
  }
  return [...by.values()].sort((a, b) => a.online - b.online || a.self - b.self);
}

function sizeCanvas() {
  const cv = NW.cv; if (!cv) return;
  NW.dpr = Math.min(2, window.devicePixelRatio || 1);
  NW.W = cv.clientWidth || 600; NW.H = cv.clientHeight || 520;
  cv.width = Math.round(NW.W * NW.dpr); cv.height = Math.round(NW.H * NW.dpr);
  NW.sprite = {};
}

function resetView() {
  const h = NW.home; NW.lon0 = h ? h.lon : 10; NW.lat0 = h ? Math.max(-35, Math.min(35, h.lat)) : 22; NW.zoom = 1;
}

function mountGlobe() {
  const cv = $('#nw-globe'); if (!cv) return;
  NW.cv = cv; NW.g = cv.getContext('2d'); sizeCanvas();
  if (!NW.mounted) resetView();
  NW.mounted = true;
  const pause = () => { NW.idleUntil = performance.now() + 5000; };
  const pt = new Map();
  cv.onpointerdown = (e) => {
    pt.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pt.size === 1) NW.drag = { x: e.clientX, y: e.clientY, lon: NW.lon0, lat: NW.lat0, moved: false };
    else if (pt.size === 2) { const [a, b] = [...pt.values()]; NW.pinch = { d: Math.hypot(a.x - b.x, a.y - b.y), z: NW.zoom }; NW.drag = null; }
    cv.setPointerCapture(e.pointerId); pause();
  };
  cv.onpointermove = (e) => {
    if (pt.has(e.pointerId)) pt.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (NW.pinch && pt.size === 2) { const [a, b] = [...pt.values()]; NW.zoom = Math.max(0.7, Math.min(6, NW.pinch.z * Math.hypot(a.x - b.x, a.y - b.y) / NW.pinch.d)); pause(); return; }
    if (NW.drag) {
      const k = 180 / (Math.PI * NW.R);
      const dx = e.clientX - NW.drag.x; const dy = e.clientY - NW.drag.y;
      if (Math.abs(dx) + Math.abs(dy) > 3) NW.drag.moved = true;
      NW.lon0 = ((NW.drag.lon - dx * k + 540) % 360) - 180;
      NW.lat0 = Math.max(-80, Math.min(80, NW.drag.lat + dy * k));
      pause(); return;
    }
    hover(e);
  };
  const end = (e) => {
    pt.delete(e.pointerId);
    if (NW.drag && !NW.drag.moved && e.type === 'pointerup') pick(e);
    if (pt.size < 2) NW.pinch = null;
    if (!pt.size) NW.drag = null;
  };
  cv.onpointerup = end; cv.onpointercancel = end;
  cv.onpointerleave = () => { if (!NW.drag) tipbox(null); };
  cv.onwheel = (e) => { e.preventDefault(); NW.zoom = Math.max(0.7, Math.min(6, NW.zoom * Math.exp(-e.deltaY * 0.0015))); pause(); };
  kick();
}

function nearest(e) {
  const r = NW.cv.getBoundingClientRect(); const mx = e.clientX - r.left; const my = e.clientY - r.top;
  let best = null; let bd = 16;
  for (const s of NW.screen || []) { const d = Math.hypot(s.x - mx, s.y - my); if (d < bd) { bd = d; best = s; } }
  return best;
}
function hover(e) { const s = nearest(e); tipbox(s); NW.cv.style.cursor = s ? 'pointer' : 'grab'; }
function pick(e) {
  const s = nearest(e); tipbox(s);
  if (!s) return;
  const row = document.querySelector(`#nw-nodes tr[data-ep="${s.gp.nodes[0].endpoint}"]`);
  if (row) { row.classList.remove('fresh'); void row.offsetWidth; row.classList.add('fresh'); }
}
function tipbox(s) {
  const tb = $('#nw-tip'); if (!tb) return;
  if (!s) { tb.hidden = true; return; }
  const n = s.gp.nodes;
  const head = n.slice(0, 4).map((x) => `<b>${esc(x.name || x.endpoint.slice(0, 8) + '…')}</b> ${x.online ? '<span class="on">online</span>' : x.seen ? `seen ${dur(now() - x.last_seen)} ago` : 'announced on chain'}${x.height !== null && x.height !== undefined ? ` · height ${grp(x.height)}` : ''}`).join('<br>');
  tb.innerHTML = `${head}${n.length > 4 ? `<br>+${n.length - 4} more` : ''}<br><span class="mute">${esc(placeName(n[0]))} · ≈ ${Math.abs(s.gp.lat)}°${s.gp.lat >= 0 ? 'N' : 'S'} ${Math.abs(s.gp.lon)}°${s.gp.lon >= 0 ? 'E' : 'W'}</span>`;
  tb.hidden = false;
  const W = NW.W; tb.style.left = `${Math.min(Math.max(6, s.x + 14), W - tb.offsetWidth - 6)}px`; tb.style.top = `${Math.max(6, s.y - tb.offsetHeight - 10)}px`;
}

/* ------------------------------------------------------------------ the page */
const REGION = (() => { try { return new Intl.DisplayNames(['en'], { type: 'region' }); } catch { return null; } })();
const countryName = (cc) => { try { return (REGION && REGION.of(cc)) || cc; } catch { return cc; } };
const placeName = (n) => (n.cc ? `${n.city ? n.city + ', ' : ''}${countryName(n.cc)}` : n.nat ? 'behind NAT' : 'not placed');

function netTiles(d) {
  const c = (d && d.counts) || {};
  const tipH = LIVE.tip ? LIVE.tip.height : d ? d.tip : null;
  return [
    tile('block', `<span id="nw-h">${grp(tipH)}</span>`, `the tip of ${esc((d && d.chain) || DENOM)}`, 'hero'),
    tile('last block', LIVE.tipTime ? ago(LIVE.tipTime) : '—', 'read live from the node'),
    tile('nodes · 24 h', grp(c.seen_24h ?? '—'), `${grp(c.placed ?? 0)} on the map · ${grp(c.nat ?? 0)} behind NAT`),
    tile('online', grp(c.online ?? '—'), `in the node's peer list in the last ${d ? d.online_secs : 120}${SEP}s`),
    tile('countries', grp(c.countries ?? '—'), `${grp(c.announced ?? 0)} announced on chain`),
    tile('median score', d && d.median_score !== null && d.median_score !== undefined ? grp(d.median_score) : '—', 'penalty of connected peers, 0 = clean · no ping: the API reports no latency'),
  ].join('');
}

function countryBars(d) {
  const list = (d && d.countries) || []; const total = (d && d.counts && d.counts.seen_24h) || 0;
  const max = Math.max(1, ...list.map((c) => c.n));
  const rows = list.map((c) => `<li><span class="cc">${esc(c.cc)}</span><span class="cn">${esc(countryName(c.cc))}</span><span class="cb"><i style="width:${((c.n / max) * 100).toFixed(1)}%"></i><em style="width:${((c.online / max) * 100).toFixed(1)}%"></em></span><b>${grp(c.n)}</b></li>`).join('');
  const nat = d && d.counts && d.counts.nat ? `<li class="nat"><span class="cc">··</span><span class="cn">behind NAT, not placed</span><span class="cb"><i style="width:${((d.counts.nat / max) * 100).toFixed(1)}%"></i></span><b>${grp(d.counts.nat)}</b></li>` : '';
  return `<div class="nw-side-h"><h2>nodes by country</h2><span class="mute">${grp(total)} node${total === 1 ? '' : 's'} · 24${SEP}h</span></div>
    ${rows || nat ? `<ul class="nw-bars">${rows}${nat}</ul>` : '<div class="empty">no node seen yet</div>'}`;
}

const NODE_HEAD = ['node', 'neuron~', 'place', '>height', 'link~', '>score~', 'seen', 'on chain~'];
function nodeRows(d) {
  return (d.nodes || []).map((n) => {
    const sub = [n.role ? esc(n.role) : n.name ? short(n.endpoint) : '', n.miner ? `mines to ${ref('neuron', n.miner)}` : ''].filter(Boolean).join(' · ');
    const who = `<span class="nw-dot ${n.online ? 'on' : n.seen ? 'off' : 'ann'}"></span>${n.name ? `<b class="nm">${esc(n.name)}</b>` : `<span class="id" title="${esc(n.endpoint)}">${short(n.endpoint)}</span>`}${cp(n.endpoint)}${sub ? `<small class="sh">${sub}</small>` : ''}`;
    const neu = n.neuron ? `${ref('neuron', n.neuron)}<small class="sh">${n.neuron_from === 'announced' ? 'announced on chain' : 'default: hash of its key'}</small>` : '<span class="mute">not announced</span>';
    const has = n.height !== null && n.height !== undefined;
    // lag: behind the tip the explorer's node had when it last saw this node
    const lag = !has || n.lag === null || n.lag === undefined ? '' : n.lag <= 0 ? '<small class="sh pos">at the tip</small>' : `<small class="sh${n.lag > 6 ? ' neg' : ''}">${grp(n.lag)} behind</small>`;
    const dir = n.direction ? kind(n.direction === 'self' ? 'explorer' : n.direction) : '<span class="mute">—</span>';
    const onchain = n.announced ? `yes · ${hlink(n.announced_at)}` : '<span class="mute">no</span>';
    const seen = `${n.online ? '<span class="on">now</span>' : n.last_seen ? ago(n.last_seen) : '<span class="mute">never</span>'}${n.first_seen ? `<small class="sh">first ${ago(n.first_seen)}</small>` : ''}`;
    const cells = [who, neu, `<span class="pl">${esc(placeName(n))}</span>`, has ? `${hlink(n.height)}${lag}` : '—', dir, n.score === null || n.score === undefined ? '—' : grp(n.score), seen, onchain];
    return `<tr data-ep="${esc(n.endpoint)}">${cells.map((c, i) => `<td class="${NODE_HEAD[i].startsWith('>') ? 'r' : ''}${NODE_HEAD[i].includes('~') ? ' hide-s' : ''}">${c}</td>`).join('')}</tr>`;
  });
}

function fillNet(d) {
  NW.data = d; NW.groups = d ? groupNodes(d) : [];
  const self = d && (d.nodes || []).find((n) => n.direction === 'self' && n.lat !== null);
  NW.home = self ? { lat: self.lat, lon: self.lon } : null;
}

async function netView() {
  const st = await status();
  const [d, bl] = await Promise.all([file('network.json', 10000), LIVE.tipTime ? null : api('/blocks?limit=1')]);
  if (bl && bl.blocks && bl.blocks[0]) { const b = bl.blocks[0]; LIVE.tipTime = b.time; if (!LIVE.tip || LIVE.tip.height < b.height) LIVE.tip = { height: b.height, id: b.id, chainwork: st.chainwork }; }
  fillNet(d); NW.at = Date.now();
  viewLive = async () => {
    if (!$('#nw-globe')) return;
    if (Date.now() - NW.at > DATA_EVERY) {
      const fresh = await file('network.json'); NW.at = Date.now();
      if (fresh && (!NW.data || fresh.generated !== NW.data.generated)) {
        fillNet(fresh);
        $('#nw-side').innerHTML = countryBars(fresh);
        const tb = $('#nw-nodes'); if (tb) tb.innerHTML = nodeRows(fresh).join('');
        $('#nw-gen').innerHTML = ago(fresh.generated);
      }
    }
    $('#nw-tiles').innerHTML = netTiles(NW.data);
  };
  setTimeout(mountGlobe, 0);
  const geo = d && d.geo && d.geo.month ? ` (${esc(d.geo.month)})` : '';
  const c = (d && d.counts) || {};
  return `<p class="kick">network · ${esc(st.chain)}</p>
  <h1>who is on the <em>wire</em></h1>
  <p class="sub nw-sub">${d ? `the nodes the explorer's node has seen in the last 24 hours and the nodes the chain announces · index written <span id="nw-gen">${ago(d.generated)}</span>` : 'the map comes from the explorer\'s index (data/network.json), which is not served here yet'}</p>
  <div class="tiles" id="nw-tiles">${netTiles(d)}</div>
  <section class="nw-map">
    <div class="nw-globe-wrap">
      <canvas id="nw-globe" aria-label="a globe with the nodes placed by their addresses; drag to turn it"></canvas>
      <div class="nw-tip tipbox" id="nw-tip" hidden></div>
      <div class="nw-legend"><span><i class="nw-dot on"></i>online</span><span><i class="nw-dot off"></i>seen in 24${SEP}h</span><span><i class="nw-dot ann"></i>announced only</span>${c.nat ? `<span class="mute">${grp(c.nat)} behind NAT, not on the map</span>` : ''}</div>
      <div class="nw-ctl" role="group" aria-label="globe controls">
        <button data-nw="in" title="zoom in" aria-label="zoom in">+</button><button data-nw="out" title="zoom out" aria-label="zoom out">−</button>
        <button data-nw="spin" class="${NW.auto ? 'on' : ''}" title="turn by itself" aria-label="turn by itself">⟳</button><button data-nw="home" title="back to the explorer's node" aria-label="reset the view">◎</button>
      </div>
    </div>
    <aside class="nw-side" id="nw-side">${countryBars(d)}</aside>
  </section>
  <h2>nodes</h2>
  ${d ? table(NODE_HEAD, nodeRows(d), 'no node seen yet', 'nw-nodes') : ''}
  <p class="lede">a node here is a radio endpoint: a 32-byte key that other nodes dial over QUIC. its <a href="https://github.com/cyberia-to/cybernode/blob/main/specs/chain-wire.md#6-discovery--the-wire-obeys-the-graph" target="_blank" rel="noopener">neuron announces it</a> by two cyberlinks, antenna → its endpoint id and socket → its packed address, and every node reads those into an address book. connected nodes exchange headers, signals and checkpoints by gossip and fetch block bodies by request (<a href="https://github.com/cyberia-to/cybernode/blob/main/specs/chain-wire.md#2-gossip-topics" target="_blank" rel="noopener">chain-wire §2–3</a>).</p>
  <p class="note">peers connected to the explorer's node in the last 24 hours (bright: in its peer list now) and the nodes announced on chain, placed by their addresses at city level and rounded to ${d ? d.grid_deg : 0.5}°. a node connected to more than one of our nodes counts once; a private or NAT address gets no dot. addresses are never shown and never stored. score is a peer's penalty (chain-wire §5): 0 is clean, 100 bans it for an hour. the node reports no round-trip time, so there is no ping here. IP geolocation by <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a> Lite${geo}, CC BY 4.0; land by Natural Earth. raw: <a href="${DATA}/network.json">network.json</a></p>`;
}

document.addEventListener('click', (e) => {
  const b = e.target.closest('[data-nw]'); if (!b) return;
  const k = b.dataset.nw;
  if (k === 'in') NW.zoom = Math.min(6, NW.zoom * 1.4);
  else if (k === 'out') NW.zoom = Math.max(0.7, NW.zoom / 1.4);
  else if (k === 'home') resetView();
  else if (k === 'spin') { NW.auto = !NW.auto; b.classList.toggle('on', NW.auto); NW.idleUntil = 0; }
  if (k !== 'spin') NW.idleUntil = performance.now() + 5000;
});
window.addEventListener('resize', () => { clearTimeout(NW.rz); NW.rz = setTimeout(sizeCanvas, 120); });
